// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading ensures readiness before frame 0
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();

// Single inline schema definition


export type CalendarWipeTransitionProps = Record<string, any>;

const MONTHS = [
  "JAN",
  "FEB",
  "MAR",
  "APR",
  "MAY",
  "JUN",
  "JUL",
  "AUG",
  "SEP",
  "OCT",
  "NOV",
  "DEC",
];

const CalendarWipeTransition: React.FC<CalendarWipeTransitionProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 4,
  calendarHeaderColor = "#FF3B30",
  calendarBodyColor = "#FFFFFF",
  textColor = "#1C1C1E",
  gridColumns = 5,
  flipSpeedFrames = 3,
  wipeDurationSeconds = 1,
  wipeDirection = "left-to-right",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationFrames = durationInSeconds * fps;
  const wipeDurationFrames = Math.min(
    wipeDurationSeconds * fps,
    durationFrames / 2
  );

  // Background color handling
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Wipe Interpolations
  const wipeIn = interpolate(frame, [0, wipeDurationFrames], [0, 100], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const wipeOut = interpolate(
    frame,
    [durationFrames - wipeDurationFrames, durationFrames],
    [0, 100],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Determine clip-path based on wipe direction
  let clipPath = "";
  switch (wipeDirection) {
    case "left-to-right":
      clipPath = `polygon(${wipeOut}% 0, ${wipeIn}% 0, ${wipeIn}% 100%, ${wipeOut}% 100%)`;
      break;
    case "right-to-left":
      clipPath = `polygon(${100 - wipeIn}% 0, ${100 - wipeOut}% 0, ${
        100 - wipeOut
      }% 100%, ${100 - wipeIn}% 100%)`;
      break;
    case "top-to-bottom":
      clipPath = `polygon(0 ${wipeOut}%, 100% ${wipeOut}%, 100% ${wipeIn}%, 0 ${wipeIn}%)`;
      break;
    case "bottom-to-top":
      clipPath = `polygon(0 ${100 - wipeIn}%, 100% ${100 - wipeIn}%, 100% ${
        100 - wipeOut
      }%, 0 ${100 - wipeOut}%)`;
      break;
  }

  // Grid Calculations
  // Bleed the grid slightly off-screen to ensure full coverage
  const bleed = 100;
  const effectiveWidth = width + bleed * 2;
  const effectiveHeight = height + bleed * 2;

  const columnWidth = effectiveWidth / gridColumns;
  // Standard calendar aspect ratio approx 1:1.2
  const calendarHeight = columnWidth * 1.2;
  const gridRows = Math.ceil(effectiveHeight / calendarHeight) + 1;
  const totalCalendars = gridColumns * gridRows;

  // Grid styling
  const gridGap = columnWidth * 0.15;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        transition: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: -bleed,
          left: -bleed,
          width: effectiveWidth,
          height: effectiveHeight,
          clipPath,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${gridColumns}, 1fr)`,
            gap: gridGap,
            padding: gridGap,
            width: "100%",
            height: "100%",
          }}
        >
          {Array.from({ length: totalCalendars }).map((_, i) => {
            // Deterministic random offsets for each calendar
            const seed = random(i);
            const startMonth = Math.floor(seed * 12);
            const startDay = Math.floor(random(i + 100) * 28);

            // Calculate current displayed values
            const flipPhase = Math.floor(frame / flipSpeedFrames);
            const currentMonthIndex = (startMonth + flipPhase) % 12;
            const currentDayNumber =
              ((startDay + flipPhase * 2) % 31) + 1;

            // Optional: simulate page turning mechanical vibration
            const isMidFlip = frame % flipSpeedFrames < flipSpeedFrames / 2;
            const scaleY = isMidFlip ? 0.95 : 1;

            return (
              <div
                key={i}
                style={{
                  backgroundColor: calendarBodyColor,
                  borderRadius: "12%",
                  overflow: "hidden",
                  display: "flex",
                  flexDirection: "column",
                  boxShadow: "0 10px 25px rgba(0,0,0,0.25)",
                  position: "relative",
                  aspectRatio: "1 / 1.15",
                }}
              >
                {/* Spiral Rings */}
                <div
                  style={{
                    position: "absolute",
                    top: "10%",
                    left: "20%",
                    width: "12%",
                    height: "15%",
                    backgroundColor: "#E5E5EA",
                    borderRadius: "20px",
                    boxShadow: "inset 0 2px 4px rgba(0,0,0,0.5)",
                    zIndex: 2,
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    top: "10%",
                    right: "20%",
                    width: "12%",
                    height: "15%",
                    backgroundColor: "#E5E5EA",
                    borderRadius: "20px",
                    boxShadow: "inset 0 2px 4px rgba(0,0,0,0.5)",
                    zIndex: 2,
                  }}
                />

                {/* Calendar Header */}
                <div
                  style={{
                    backgroundColor: calendarHeaderColor,
                    height: "35%",
                    width: "100%",
                    borderBottom: "2px solid rgba(0,0,0,0.1)",
                  }}
                />

                {/* Calendar Body */}
                <div
                  style={{
                    height: "65%",
                    width: "100%",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    color: textColor,
                    transform: `scaleY(${scaleY})`,
                    transformOrigin: "top",
                  }}
                >
                  <div
                    style={{
                      fontSize: `${columnWidth * 0.15}px`,
                      fontWeight: 700,
                      letterSpacing: "0.05em",
                      opacity: 0.8,
                      marginBottom: "2%",
                    }}
                  >
                    {MONTHS[currentMonthIndex]}
                  </div>
                  <div
                    style={{
                      fontSize: `${columnWidth * 0.45}px`,
                      fontWeight: 800,
                      lineHeight: 0.9,
                    }}
                  >
                    {currentDayNumber.toString().padStart(2, "0")}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CalendarWipeTransition;